const rows = Array.isArray($json.list) ? $json.list : [];
return rows
  .filter((row) => row && row.Id && String(row.company_name || '').trim())
  .map((row, index) => ({ json: { Id: row.Id, company_name: String(row.company_name).trim() }, pairedItem: { item: index } }));

const companyName = String($json.company_name || '').trim();
const query = companyName.replace(/"/g, '') + ' Singapore';
return {
  json: {
    ...$json,
    openserp_query: query,
    openserp_url: 'https://searxng-railway-production-518a.up.railway.app/google/search?text=' + encodeURIComponent(query) + '&limit=10'
  }
};

const row = $('Build OpenSERP Query').first().json || {};
const searchItems = $('Search OpenSERP').all();
const rawResults = searchItems.flatMap((item) => {
  const payload = item.json ?? {};
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.body)) return payload.body;
  if (Array.isArray(payload.results)) return payload.results;
  if (Array.isArray(payload.data)) return payload.data;
  if (Array.isArray(payload.items)) return payload.items;
  if (payload.title || payload.url || payload.link) return [payload];
  return [];
});
const topResults = rawResults.slice(0, 10).map((result, index) => ({
  rank: index + 1,
  title: String(result.title || '').trim(),
  url: String(result.url || result.link || '').trim(),
  snippet: String(result.content || result.snippet || result.description || '').trim()
}));
const prompt = [
  'Pick the best official website URL from the Google search results.',
  'Company: ' + row.company_name,
  'Rules:',
  '- Prefer the official company or clinic homepage.',
  '- Reject directories, reviews, social media, maps, job boards, articles, PDFs, and unrelated pages.',
  '- If none is clearly official, return an empty url.',
  '- Return JSON only: {"url":"","reason":""}',
  'Search results:',
  JSON.stringify(topResults, null, 2)
].join('\n');
return {
  json: {
    Id: row.Id,
    company_name: row.company_name,
    openserp_query: row.openserp_query,
    openserp_results: topResults,
    body: {
      model: 'deepseek/deepseek-v4-flash',
      temperature: 0,
      messages: [
        { role: 'system', content: 'You select official company homepage URLs from Google search results. Return strict JSON only.' },
        { role: 'user', content: prompt }
      ]
    }
  }
};

function stripFences(value) {
  const fence = String.fromCharCode(96).repeat(3);
  return String(value || '').replace(fence + 'json', '').replaceAll(fence, '').trim();
}
function normalizeUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(https?:\/\/[^\s?#]+)(?:[?#].*)?$/i);
  return match ? match[1].replace(/\/+$/, '/') : '';
}
const prepared = $('Prepare OpenSERP Pick').first().json || {};
const response = $json || {};
const content = String(response.choices?.[0]?.message?.content || response.body?.choices?.[0]?.message?.content || '').trim();
let parsed = {};
try { parsed = JSON.parse(stripFences(content)); } catch {}
const pickedUrl = normalizeUrl(parsed.url || '');
const evidence = {
  query: prepared.openserp_query,
  picked_url: pickedUrl,
  reason: String(parsed.reason || '').trim(),
  first_10_results: prepared.openserp_results || [],
  llm_raw: content
};
return {
  json: {
    Id: prepared.Id,
    company_name: prepared.company_name,
    url_picked: pickedUrl,
    search_evidence_json: JSON.stringify(evidence),
    status: pickedUrl ? 'url picked' : 'no url picked',
    last_stage: 'url_pick',
    last_error: pickedUrl ? '' : 'No official URL selected from first 10 OpenSERP Google results'
  }
};
